let aRoute=academyRoute(location.hash),aLabels={},aPaths=[],aCareers=null,aAbroad=null,aOpps=null,aStep=null,aTab='read',aWalk=0,aQuery='',aSearchPage=0,aFormat='all',aSubject='all',aError=false,aLoading=true,aGeneration=0,aQuizIndex=0,aInterestAnswers=[],aInterestResults=null,aDestination='etats-unis',aOpportunityType='all',aSchoolPilot=null,aSchoolPractice=null,aPracticeIndex=0;
state.academy=academySafeState(state.academy);if(!['light','dark'].includes(state.theme))state.theme=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';state.lowData=state.lowData??true;
const at=k=>aLabels[k]?.[state.lang]||aLabels[k]?.fr||k;
const aLabel=(fr,en)=>state.lang==='en'&&en?en:fr;
const aLink=(route,key,cls='secondary')=>`<a class="${cls}" href="${route}">${esc(at(key))}</a>`;
const aStatus=()=>`<span class="a-badge">${esc(at('draft'))}</span>`;
const aFetch=async url=>{const r=await fetch(url);if(!r.ok)throw Error('unavailable');return r.json()};
const aPath=id=>aPaths.find(p=>p.id===id);
const aPersist=()=>{persist();};
function aPageHead(key,sub=''){return `<header class="a-page-head"><span class="eyebrow">NUNYA · ACADÉMIE</span><h1>${esc(at(key))}</h1>${sub?`<p>${esc(sub)}</p>`:''}</header>`}
function aNav(){const groups=[['learning',[['accueil','grid','home'],['avenir','compass','future'],['mes-cours','book','school'],['bibliotheque','search','library']]],['space',[['revision','calendar','review'],['progression','chart','progress'],['portfolio','award','portfolio'],['hors-ligne','download','downloads'],['profil','grid','profile'],['aide','help','help']]]];const nav=$('#sidebar nav');nav.innerHTML=groups.map(([heading,items],i)=>`${i?'<div class="nav-rule"></div>':''}<span class="nav-label">${esc(at(heading))}</span>${items.map(([route,ico,key])=>`<a class="nav-item ${aRoute.nav===route?'active':''}" href="#/${route}" ${aRoute.nav===route?'aria-current="page"':''}>${icon(ico)}<span>${esc(at(key))}</span></a>`).join('')}`).join('');$('.sidebar>.nav-label')?.remove();$$('.feedback-nav').forEach(x=>x.remove());$('.sidebar-bottom .offline-note')?.remove();let bottom=$('.bottom-nav');if(!bottom){bottom=document.createElement('nav');bottom.className='bottom-nav';bottom.setAttribute('aria-label','Navigation mobile');document.body.append(bottom)}const bottomItems=[['accueil','grid',aLabel('Accueil','Home')],['apprendre','monitor',aLabel('Coder','Code')],['mes-cours','book',aLabel('Mes cours','My classes')],['avenir','compass',aLabel('Mon avenir','My future')]],inMore=!bottomItems.some(([route])=>route===aRoute.nav);bottom.innerHTML=bottomItems.map(([route,ico,label])=>`<a href="#/${route}" ${aRoute.nav===route?'aria-current="page"':''} class="${aRoute.nav===route?'active':''}">${icon(ico)}<span>${esc(label)}</span></a>`).join('')+`<button id="a-more" aria-expanded="false" class="${inMore?'active':''}">${icon('menu')}<span>${esc(at('more'))}</span></button>`;$('#help-btn').onclick=()=>aGo('#/aide');$('.brand').href='#/accueil';$('#breadcrumb-current').textContent=at(({accueil:'home',avenir:'future','mes-cours':'school',bibliotheque:'library',etranger:'abroad',opportunites:'opportunities',portfolio:'portfolio',revision:'review',progression:'progress','hors-ligne':'downloads',profil:'profile',aide:'help',ressource:'library',sources:'methodology',confidentialite:'privacy'})[aRoute.nav]||'home');document.title=`${$('#breadcrumb-current').textContent} · Nunya`;$('#search-btn').onclick=()=>aGo('#/bibliotheque');$('#language-btn').onclick=()=>{state.lang=state.lang==='en'?'fr':'en';aPersist();render()};$('#language-btn').setAttribute('aria-label',state.lang==='en'?'Language: English':'Langue : français');if(!$('#a-feedback'))$('.sidebar-bottom').insertAdjacentHTML('afterbegin',`<button class="help-button" id="a-feedback">${icon('heart')}<span>${esc(at('feedback'))}</span></button>`);$('#a-feedback').onclick=()=>feedbackModal();const p=aPath(state.academy.activePath);let chip=$('#a-path-chip');if(!chip){chip=document.createElement('a');chip.id='a-path-chip';chip.className='a-path-chip';$('.topbar').append(chip)}chip.hidden=!p||aRoute.nav!=='avenir';if(p){const next=academyNext(p,state.academy.progress);chip.href='#/parcours/'+p.id;chip.textContent=`${at('path')} : ${p.title_fr} · ${at('stage')} ${next?Math.max(1,next.stageIndex):p.stages.length-1}/${p.stages.length-1}`}syncMenuAccess();}
const aLegacyRender=render;
render=function(){if(!Object.keys(aLabels).length){aLegacyRender();return}const legacy=['profil','revision','progression','hors-ligne','ressource','confidentialite'].includes(aRoute.kind);if(aRoute.kind==='ressource'){document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.add('resource-study');$('#main').innerHTML=studio&&studio.id===aRoute.id?studioMarkup():`<div class="a-loading" role="status">${esc(at('load'))}</div>`;applyAccent();hydrate();wireStudyLinks()}else if(legacy){if(aRoute.kind==='profil'){page='home';academySection='profile'}if(aRoute.kind==='confidentialite'){page='home';academySection='privacy'}if(aRoute.kind==='revision'){page='home';academySection='review'}if(aRoute.kind==='progression'){page='progress';academySection=null}if(aRoute.kind==='hors-ligne'){page='downloads';academySection=null}aLegacyRender();if(aRoute.kind==='hors-ligne')$('#main').insertAdjacentHTML('afterbegin',aSavedBundles());}else{academySection=null;page=aRoute.kind==='bibliotheque'?'explore':aRoute.kind==='avenir'?'careers':'home';document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.toggle('low-data',state.lowData);document.documentElement.lang=state.lang==='en'?'en':'fr-TG';$('#main').innerHTML=aLoading?`<div class="a-loading" role="status">${esc(at('load'))}</div>`:aError?`<section class="a-empty"><h1>${esc(at('notDownloaded'))}</h1><button class="primary" data-a="retry">${esc(at('retryLoad'))}</button>${aLink('#/hors-ligne','downloads')}</section>`:aView();applyAccent();hydrate();}aNav();$('#language-label').textContent=state.lang.toUpperCase();$('#profile-btn').textContent=(state.profile.name||'N').slice(0,1).toUpperCase();document.body.classList.toggle('a-step-route',aRoute.kind==='step');document.body.classList.toggle('a-school-route',aRoute.nav==='mes-cours');if(aRoute.kind==='step'&&aStep){const p=aPath(aRoute.id);document.title=`${aStep.title_fr} · ${p?.title_fr||''} · Nunya`;}aRenderMath();};
function aGo(route,replace=false){if(typeof speechSynthesis!=='undefined')speechSynthesis.cancel();stopRuntime();closeModal();$('#sidebar').classList.remove('open');if(replace)history.replaceState({},'',route);else history.pushState({},'',route);const pending=aResolve();window.scrollTo({top:0,behavior:'instant'});return pending;}
async function aResolve(){const generation=++aGeneration;aError=false;aRoute=academyRoute(location.hash);if(location.hash!==aRoute.canonical)history.replaceState({},'',aRoute.canonical);aLoading=true;render();try{if(aRoute.kind==='mes-cours'&&aRoute.id==='catalogue')await references();if(aRoute.kind==='avenir'&&!aCareers)aCareers=await aFetch('./data/careers_togo.json');if(aRoute.kind==='etranger'&&!aAbroad)aAbroad=await aFetch('./data/abroad_guides.json');if(aRoute.kind==='opportunites'&&!aOpps)aOpps=await aFetch('./data/opportunities.json');if(aRoute.kind==='step'){if(!aRoute.id.startsWith('cours-')){state.academy.activePath=aRoute.id;aPersist()}aTab='read';aWalk=0;if(aRoute.id?.startsWith('cours-')){if(aRoute.id==='cours-maths-seconde'&&!aSchoolPractice)aSchoolPractice=await aFetch('./data/school_practice.json');aStep=aCourseStep(aRoute.id.slice(6),aRoute.stepId);}else{try{aStep=await aFetch('./data/steps/'+encodeURIComponent(aRoute.id)+'/'+encodeURIComponent(aRoute.stepId)+'.json')}catch{const pack=await aFetch('./data/paths/'+encodeURIComponent(aRoute.id)+'.json');aStep=pack.stages.flatMap(s=>s.steps).find(s=>s.id===aRoute.stepId)}}if(aStep?.course?.id==='maths-seconde'){if(!aSchoolPilot)aSchoolPilot=await aFetch('./data/school_pilot.json');aStep.math=aSchoolPilot.math[Number(aStep.id)]}if(!aStep)throw Error('step');aPracticeIndex=academyPracticeProgress(aStep,aRoute.id,state.academy.answers,state.academy.practice[aRoute.id+'-'+aStep.id]).index}if(generation!==aGeneration)return;aLoading=false;if(aRoute.kind==='ressource'){aLoading=false;await openResource(aRoute.id,false);return}render();$('#main').focus({preventScroll:true});}catch{if(generation!==aGeneration)return;aLoading=false;aError=true;render()}}
function aView(){if(aRoute.kind==='accueil')return aHome();if(aRoute.kind==='avenir')return aFuture();if(aRoute.kind==='path')return aPathView();if(aRoute.kind==='step')return aStepView();if(aRoute.kind==='mes-cours')return aSchool();if(aRoute.kind==='bibliotheque')return aLibrary();if(aRoute.kind==='etranger')return aAbroadView();if(aRoute.kind==='opportunites')return aOpportunityView();if(aRoute.kind==='portfolio')return aPortfolio();if(aRoute.kind==='aide')return aHelp();if(aRoute.kind==='sources')return aPageHead('methodology')+`<section class="panel"><p>${esc(at('sourcesIntro'))}</p>${aLink('#/aide','help')}</section>`;return aPageHead('unknown')+aLink('#/accueil','goHome','primary')}
function aHome(){const p=aPath(state.academy.activePath),next=p&&academyNext(p,state.academy.progress),name=state.profile.name;return `<section class="a-home-hero"><span class="eyebrow">${esc(at('hello'))}${name?', '+esc(name):''}</span><h1>${esc(at('findGoal'))}</h1><p>${esc(at('homeSubtitle'))}</p></section>${!state.academy.onboarded&&!name?`<form id="a-onboard" class="panel a-onboard"><h2>${esc(at('first'))}</h2><label>${esc(at('name'))}<input name="name" maxlength="30" autocomplete="nickname"></label><label>${esc(at('goal'))}<select name="goal"><option value="school">${esc(at('startSchool'))}</option><option value="future">${esc(at('findSkills'))}</option><option value="both">${esc(at('both'))}</option></select></label><label class="a-check"><input type="checkbox" name="age" required>${esc(at('age'))}</label><small>${esc(at('ageNote'))}</small><p>${esc(at('firstNote'))}</p><button class="primary">${esc(at('start'))}</button></form>`:''}${p?`<section class="a-resume"><div><span class="eyebrow">${esc(at('resume'))}</span><h2>${esc(p.title_fr)}</h2><p>${next?esc(next.title_fr)+' · '+next.minutes+' '+at('minutes'):esc(at('completePath'))}</p>${aProgress(p)}</div>${aLink(next?'#/parcours/'+p.id+'/etape/'+next.id:'#/portfolio',next?'resume':'portfolio','primary')}</section>`:''}<div class="a-track-grid"><a href="#/mes-cours" class="a-track"><span>${icon('book')}</span><h2>${esc(at('school'))}</h2><p>${esc(at('startSchool'))}</p><b>01 →</b></a><a href="#/avenir" class="a-track"><span>${icon('compass')}</span><h2>${esc(at('future'))}</h2><p>${esc(at('findSkills'))}</p><b>02 →</b></a></div><section class="a-section"><div class="section-heading"><h2>${esc(at('browse'))}</h2>${aLink('#/avenir','future','text-button')}</div><div class="a-path-grid">${['cybersecurite','sante-sciences','agriculture-projets'].map(id=>aPath(id)).filter(Boolean).map(aPathCard).join('')}</div></section><section class="a-review-strip"><div><h2>${esc(at('daily'))}</h2><p>${esc(at('review'))} · 5 ${esc(at('minutes'))}</p></div>${aLink('#/revision','toPractice')}</section>`}
function aPathCard(p){return `<a href="#/parcours/${p.id}" class="a-path-card"><span class="a-path-icon">${icon(p.id==='cybersecurite'?'briefcase':p.id==='developpement-web'?'monitor':'chart')}</span><span class="eyebrow">${esc(at('beginner'))} · ≈ ${p.total_hours.toFixed(1)} ${at('hours')}</span><h3>${esc(aLabel(p.title_fr,p.title_en))}</h3><p>${esc(p.summary_fr)}</p><span>${esc(at('discover'))} →</span></a>`}
function aProgress(p){const steps=academySteps(p),done=steps.filter(x=>state.academy.progress[x.id]?.complete).length;return `<div class="a-progress" role="progressbar" aria-label="${esc(p.title_fr)}" aria-valuemin="0" aria-valuemax="${steps.length}" aria-valuenow="${done}"><span style="width:${done/steps.length*100}%"></span></div><small>${done}/${steps.length} ${esc(at('finished'))}</small>`}
function aFuture(){if(aRoute.careerId){const c=aCareers.find(c=>c.id===aRoute.careerId);return c?aCareerView(c):aPageHead('unknown')}if(aRoute.id==='interets')return aInterestView();const domain=SECTORS.find(s=>s.id===aRoute.id);if(domain){const list=aCareers.filter(c=>c.domain_id===domain.id);return aLink('#/avenir','back','back-link')+`<header class="a-page-head"><h1>${esc(domain.title)}</h1><p>${esc(domain.desc)}</p></header>${aPaths.filter(p=>(p.domain_id||'tech')===domain.id).map(p=>`<section class="a-resume"><div><h2>${esc(p.title_fr)}</h2><p>${esc(p.depth_fr||p.summary_fr)} · ≈ ${p.total_hours.toFixed(1)} h</p></div>${aLink('#/parcours/'+p.id,'start','primary')}</section>`).join('')}<div class="a-career-grid">${list.map(c=>`<a class="a-career-card" href="#/avenir/${domain.id}/${c.id}"><h2>${esc(c.title_fr)}</h2><p>${esc(c.summary_fr)}</p><span>${esc(at('discover'))} →</span></a>`).join('')}</div>`}return aPageHead('future',at('futureSubtitle'))+(FEATURES.showAbroad||FEATURES.showOpportunities?`<div class="a-track-grid">${FEATURES.showAbroad?`<a href="#/etranger" class="a-track"><span>${icon('globe')}</span><h2>${esc(at('abroad'))}</h2><p>${esc(aLabel('Pays, démarches et liste de préparation.','Countries, steps and a preparation checklist.'))}</p><b>→</b></a>`:''}${FEATURES.showOpportunities?`<a href="#/opportunites" class="a-track"><span>${icon('briefcase')}</span><h2>${esc(at('opportunities'))}</h2><p>${esc(aLabel('Bourses, stages et portes d’entrée officielles.','Scholarships, internships and official entry points.'))}</p><b>→</b></a>`:''}</div>`:'')+`<section class="a-section"><div class="section-heading"><h2>${esc(at('browse'))}</h2>${aLink('#/avenir/interets','interest','text-button')}</div><div class="a-path-grid">${['cybersecurite','sante-sciences','agriculture-projets'].map(id=>aPath(id)).filter(Boolean).map(aPathCard).join('')}</div></section><section class="a-section"><h2>${esc(at('allDomains'))}</h2><div class="a-domain-grid">${SECTORS.slice(0,9).map(aDomainCard).join('')}</div><details class="a-more-domains"><summary>${esc(at('more'))} · 4</summary><div class="a-domain-grid">${SECTORS.slice(9).map(aDomainCard).join('')}</div></details></section>`}
function aDomainCard(s){const ico={tech:'monitor',health:'heart',agri:'leaf',energy:'bolt',logistics:'briefcase',business:'chart',creative:'award',services:'help',telecom:'wifi',fintech:'chart',education:'book',environment:'leaf',construction:'grid'}[s.id];return `<a class="a-domain-card" href="#/avenir/${s.id}">${icon(ico)}<h3>${esc(s.title)}</h3><span>${esc(at('discover'))} →</span></a>`}
function aCareerView(c){const p=aPaths.find(p=>p.career_id===c.id||p.id===c.id)||aPaths.find(p=>p.domain_id===c.domain_id),old=SECTORS.find(s=>s.id===c.domain_id);return aLink('#/avenir/'+c.domain_id,'back','back-link')+`<header class="a-page-head"><span class="eyebrow">${esc(old?.title||'')}</span><h1>${esc(c.title_fr)}</h1><p>${esc(c.summary_fr)}</p>${aStatus()}</header>${p?`<section class="a-resume"><div><h2>${esc(p.title_fr)}</h2><p>≈ ${p.total_hours.toFixed(1)} h · ${esc(at('beginner'))}</p></div>${aLink('#/parcours/'+p.id,'start','primary')}</section>`:`<section class="panel"><h2>${esc(at('discover'))}</h2><p>${esc(c.daily_life_fr)}</p><p>${esc(at('soon'))}</p>${aLink('#/parcours/cours-digital','start')}</section>`}<div class="a-detail-columns"><section class="panel"><h2>${esc(at('dailyLife'))}</h2><p>${esc(c.daily_life_fr)}</p><h3>${esc(at('skills'))}</h3><ul>${c.skills.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="panel"><h2>${esc(at('schoolBridge'))}</h2><p>${esc(at('schoolBridgeNote'))}</p>${aLink('#/mes-cours','school')}<p>${c.school_subjects.map(s=>esc(({maths:'Mathématiques',english:'Anglais',french:'Français',physics:'Physique-Chimie',biology:'SVT',history:'Histoire-Géographie',civics:'ECM'})[s]||s)).join(' · ')}</p></section></div><details class="panel a-source-panel"><summary>${esc(at('sources'))} · ${esc(at('confirm'))}</summary><p>${esc(at('admissionNote'))}</p><h3>${esc(at('studyTogo'))}</h3><ul>${c.where_to_study_togo.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>${esc(at('workTogo'))}</h3><ul>${c.where_to_work_togo.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${c.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a> · ${esc(s.retrieved_on)}</p>`).join('')}</details>${old?`<details class="panel"><summary>${esc(at('project'))}</summary>${projectPanel(old)}</details>`:''}`}
function aPathView(){if(aRoute.id?.startsWith('cours-'))return aCourseOverview(aRoute.id.slice(6));const p=aPath(aRoute.id);if(!p)return aPageHead('unknown');const next=academyNext(p,state.academy.progress),first=p.stages[0],weekly=state.academy.weekly[p.id]||3,remaining=academySteps(p).filter(s=>!state.academy.progress[s.id]?.complete).reduce((n,s)=>n+s.minutes,0),target=new Date(Date.now()+remaining/60/weekly*7*86400000);return `<div class="a-crumb">${aLink('#/avenir','future','text-button')} / ${esc(p.title_fr)}</div><header class="a-path-hero"><span class="eyebrow">${esc(at('beginner'))} · ≈ ${p.total_hours.toFixed(1)} h</span><h1>${esc(p.title_fr)}</h1><p>${esc(p.summary_fr)}</p>${aStatus()}<div class="a-hero-actions">${aLink(next?'#/parcours/'+p.id+'/etape/'+next.id:'#/portfolio',next?(state.academy.activePath===p.id?'resume':'start'):'portfolio','primary')}<button class="secondary" data-a="download-path" data-id="${p.id}">${esc(at('downloadPath'))} · ≈ ${p.offline_bundle_size_kb} Ko</button></div>${aProgress(p)}</header><div class="a-detail-columns"><section class="panel"><h2>${esc(at('outcomes'))}</h2><ul>${p.outcomes_fr.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="panel"><h2>${esc(at('prerequisites'))}</h2><ul>${p.prerequisites.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${first.checkpoint_id?`<button class="text-button" data-a="testout" data-stage="${first.id}">${esc(at('testout'))} →</button>`:''}</section></div><section class="a-roadmap"><details class="a-intro panel" open><summary>0 · ${esc(first.title_fr)}</summary><p>${esc(first.goal_fr)}</p>${aStepList(p,first)}</details>${p.stages.slice(1).map((s,i)=>`<article class="a-stage panel" data-stage="${s.id}"><header><span class="a-stage-number">${i+1}</span><div><h2>${esc(s.title_fr)}</h2><p>${esc(s.goal_fr)} · ${Math.round(s.estimated_hours*60)} min</p></div></header>${aStepList(p,s)}<button class="text-button" data-a="testout" data-stage="${s.id}">${esc(at('testout'))} →</button></article>`).join('')}</section><form id="a-weekly" class="panel"><h2>${esc(at('weekly'))}</h2><label>${esc(at('weeklyHours'))}<input name="hours" type="number" min="0.5" max="20" step="0.5" value="${weekly}" required></label><p>${esc(at('target'))} : ${target.toLocaleDateString(state.lang==='en'?'en-US':'fr-TG',{day:'numeric',month:'long',year:'numeric'})}</p><small>${esc(at('estimate'))}</small><button class="secondary">${esc(at('plan'))}</button></form><section class="a-review-strip"><div><h2>${esc(at('sources'))}</h2><p>${esc(at('admissionNote'))}</p></div>${aLink('#/avenir/'+(p.domain_id||'tech')+'/'+p.career_id,'discover')}</section>`}
function aStepList(p,s){return `<ol class="a-step-list">${s.steps.map(step=>{const school=p.id.startsWith('cours-'),id=p.id.slice(6),done=school?state.done.includes(id+':'+step.id):state.academy.progress[step.id]?.complete,unlocked=school?step.id==='0'||done||state.done.includes(id+':'+(Number(step.id)-1))||state.courseAccess?.[id]:academyUnlocked(p,step.id,state.academy.progress);return `<li><a href="#/parcours/${p.id}/etape/${step.id}" class="${done?'done':unlocked?'available':'locked'}"><span>${done?'✓':step.type==='checkpoint'?'◎':'○'}</span><span>${esc(step.title_fr)}<small>${step.minutes} min · ${esc(at(done?'finished':unlocked?'available':'todo'))}</small></span><span>→</span></a>${!unlocked?`<small class="a-unlock-note">${esc(at('locked'))}</small>`:''}</li>`}).join('')}</ol>`}
function aCourseMeta(id){const c=getCourse(id);if(!c)return null;return {id:'cours-'+id,title_fr:c.title,total_hours:c.duration/60,stages:[{id:'unite',title_fr:c.title,steps:c.lessons.map((l,i)=>({id:String(i),title_fr:l.title,minutes:10,type:'leçon'}))}]}}
function aCourseOverview(id){const c=getCourse(id);if(!c)return aPageHead('unknown');const p=aCourseMeta(id),next=c.lessons.findIndex((_,i)=>!state.done.includes(id+':'+i)),n=next<0?0:next;return aLink('#/mes-cours','back','back-link')+`<header class="a-path-hero"><span class="eyebrow">${esc(c.category)}</span><h1>${esc(c.title)}</h1><p>${esc(c.desc)}</p>${aStatus()}<div class="a-hero-actions">${aLink('#/parcours/cours-'+id+'/etape/'+n,next>0?'resume':'start','primary')}<button class="secondary" data-a="download-course" data-id="${id}">${esc(at('downloadUnit'))} · ≈ ${Math.ceil(JSON.stringify(c).length*1.5/1024)} Ko</button></div></header><section class="panel"><ol class="a-step-list">${c.lessons.map((l,i)=>{const locked=i>0&&!state.done.includes(id+':'+(i-1))&&!state.courseAccess?.[id];return `<li><a href="#/parcours/cours-${id}/etape/${i}"><span>${state.done.includes(id+':'+i)?'✓':String(i+1).padStart(2,'0')}</span><span>${esc(l.title)}<small>${esc(at(locked?'todo':'available'))}</small></span><span>→</span></a>${locked?`<small>${esc(at('locked'))}</small>`:''}</li>`}).join('')}</ol></section><details class="panel"><summary>${esc(at('schoolUseful'))}</summary>${aLink('#/avenir','future')}</details>`}
function aCourseStep(id,index){const c=getCourse(id),n=Number(index),l=c?.lessons[n];if(!l)return null;return {id:String(n),type:'leçon',title_fr:l.title,body:[l.body],minutes:10,example:{input:l.code||'',output:l.output||'',explanation:l.explanation||''},walkthrough:[{title:l.title,text:l.body},{title:at('practice'),text:l.explanation}],practice:[{id:'course-'+id+'-'+n,type:'mcq',prompt:l.question,options:l.options,answer:l.answer,explanation:l.explanation,hints:[l.body,l.explanation]},...(aSchoolPractice?.courses?.[id]?.[String(n)]||[])],code:l.code,course:c,courseIndex:n,license:'CC BY-SA 4.0'}}
function aStepView(){const p=aRoute.id.startsWith('cours-')?aCourseMeta(aRoute.id.slice(6)):aPath(aRoute.id),s=aStep;if(!p||!s)return aPageHead('unknown');const unlocked=s.course?Number(s.id)===0||state.done.includes(s.course.id+':'+(Number(s.id)-1))||state.done.includes(s.course.id+':'+s.id)||state.courseAccess?.[s.course.id]:academyUnlocked(p,s.id,state.academy.progress);if(!unlocked&&!aRoute.challenge)return `<section class="a-empty"><h1>${esc(s.title_fr)}</h1><p>${esc(at('locked'))}</p>${aLink('#/parcours/'+p.id,'back','primary')}</section>`;const meta=academySteps(p).find(x=>x.id===s.id),stage=p.stages.find(x=>x.id===meta?.stageId)||p.stages[0];return `${s.course?`<div class="a-crumb"><a href="${aRoute.canonical.replace(/\/\d+$/,'')}">${esc(p.title_fr)}</a> › Leçon ${Number(s.id)+1} sur ${s.course.lessons.length} › ${esc(s.title_fr)}</div>`:`<div class="a-crumb"><a href="#/parcours/${p.id}">${esc(p.title_fr)}</a> › ${esc(at('stage'))} ${Math.max(1,meta?.stageIndex||0)}/${p.stages.length-1} › ${esc(s.title_fr)}</div>`}<div class="a-learning-layout"><aside class="a-step-aside"><h2>${esc(stage.title_fr)}</h2>${aStepList(p,stage)}</aside><article class="a-lesson"><header><span class="eyebrow">${s.minutes} min · ${esc(at(s.type==='checkpoint'?'checkpoint':'step'))}</span><h1>${esc(s.title_fr)}</h1>${aStatus()}</header><nav class="a-lesson-tabs" aria-label="${esc(at('learning'))}">${['read','walk','practice'].map(k=>`<button data-a="tab" data-tab="${k}" aria-pressed="${aTab===k}">${esc(at(k))}</button>`).join('')}</nav><div id="a-lesson-panel">${aStepPanel()}</div><details class="a-reflection"><summary>${esc(at('write'))}</summary><textarea id="a-note" rows="3" maxlength="4000">${esc(state.academy.notes[p.id+'-'+s.id]||'')}</textarea></details><footer class="a-lesson-footer"><div><button class="text-button" data-a="save-work">${esc(at('save'))}</button><button class="text-button" data-a="blocked">${esc(at('blocked'))}</button></div>${aStepPrimaryButton()}</footer></article></div>`}
function aStepCodeLanguage(){if(aStep?.coding)return aStep.coding.language;if(!aStep?.course)return null;if(aStep.course.id==='web')return [null,'html','html','javascript',null,'html'][aStep.courseIndex];return codeLanguage(aStep.course)}
function aStepPanel(){const s=aStep;if(aTab==='walk'){const w=s.walkthrough||[];aWalk=Math.max(0,Math.min(w.length-1,aWalk));return `<span class="eyebrow">${aWalk+1}/${w.length}</span><h2>${esc(w[aWalk]?.title||s.title_fr)}</h2><p>${esc(w[aWalk]?.text||'')}</p><div class="a-inline-actions"><button class="secondary" data-a="walk-prev" ${aWalk===0?'disabled':''}>${esc(at('previous'))}</button><button class="secondary" data-a="walk-next">${esc(at(aWalk===w.length-1?'practice':'following'))}</button></div>`}if(aTab==='practice'||s.type==='checkpoint')return `<p>${esc(at(s.type==='checkpoint'?'passTest':'unlimited'))}</p>${aPracticePanel()}${s.type==='projet'?aProjectEntry():''}`;return `${s.body.map(p=>`<p class="a-prose">${esc(p)}</p>`).join('')}${s.math?`<div data-a-math="${esc(s.math)}"></div>`:''}${s.example?`<section class="a-worked"><h2>${esc(at('discover'))}</h2><pre>${esc(s.example.input)}</pre><p><strong>${esc(s.example.output)}</strong></p><p>${esc(s.example.explanation)}</p></section>`:''}${s.type==='projet'?aProjectEntry():''}${aStepCodeLanguage()?`<button class="secondary" data-a="code">${esc(at('practice'))} · ${esc(aStepCodeLanguage())}</button><div id="a-code-panel"></div>`:''}<div class="a-inline-actions"><button class="secondary" data-a="tab" data-tab="practice">${esc(at('practice'))} →</button><button class="text-button" data-a="speak">${icon('globe')}${esc(at('listen'))}</button></div>`}
function aQuestion(q){const key=aRoute.id+'-'+q.id,w=state.academy.answers[key]||{},correct=w.checked&&w.correct;return `<section class="a-question" data-question="${esc(q.id)}" aria-labelledby="heading-${esc(q.id)}"><h2 id="heading-${esc(q.id)}" tabindex="-1">${esc(q.prompt)}</h2>${q.type==='mcq'?`<div class="a-options">${q.options.map((option,i)=>`<button class="a-option ${w.value===i?'selected':''}" data-a="answer" data-q="${q.id}" data-value="${i}" aria-pressed="${w.value===i}"><span>${String.fromCharCode(65+i)}</span>${esc(option)}</button>`).join('')}</div>`:`<label>${esc(at('answer'))}<input class="a-answer-input" data-q="${q.id}" value="${esc(w.value??'')}" ${q.type==='numeric'?'inputmode="decimal"':''} maxlength="2000"></label>${q.type==='numeric'?`<small>${esc(at('numberHint'))}</small>`:''}`}<div class="a-inline-actions"><button class="secondary" data-a="grade" data-q="${q.id}">${esc(at('check'))}</button><button class="text-button" data-a="hint" data-q="${q.id}">${esc(at('hint'))} ${w.hints||0}/3</button></div>${w.checked?`<div class="a-answer-feedback" role="status"><strong>${esc(at(correct?'correct':'retry'))}</strong><p>${esc(q.explanation)}</p></div>`:''}${w.hints?`<div class="a-hint" role="status">${esc((q.hints||aStep.hints||[])[Math.min(w.hints-1,(q.hints||aStep.hints||[]).length-1)]||q.explanation)}${w.hints>=3?`<p>${esc(q.type==='mcq'?q.options[q.answer]:q.answer)} · ${esc(q.explanation)}</p>`:''}</div>`:''}</section>`}
function aProjectEntry(){const key=aRoute.id+'-'+aStep.id,criteria=aStep.deliverable?.criteria||aStep.project_criteria||aStep.criteria||[];return `<section class="a-project-entry"><h2>${esc(at('project'))}</h2>${criteria.length?`<ul>${criteria.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<label>${esc(at('write'))}<textarea id="a-project-text" maxlength="6000" rows="6">${esc(state.academy.projects[key]||'')}</textarea></label><button class="secondary" data-a="save-project">${esc(at('saveProject'))}</button></section>`}
function aPracticeStatus(){return academyPracticeProgress(aStep,aRoute.id,state.academy.answers,aPracticeIndex)}
function aPracticePanel(){const status=aPracticeStatus(),q=aStep.practice[status.index];if(!q)return '';return `<div class="a-practice-position" role="status"><strong>Question ${status.index+1} sur ${status.total}</strong><span>${status.completed}/${status.total} validées</span></div>${aStep.course&&state.done.includes(aStep.course.id+':'+aStep.id)?'<p class="a-practice-note">Leçon déjà terminée : tes acquis sont conservés. Cette série te permet de réviser.</p>':''}${aQuestion(q)}<div class="a-inline-actions"><button class="text-button" data-a="practice-prev" ${status.index===0?'disabled':''}>← Question précédente</button></div>${status.complete?'<p class="a-answer-feedback" role="status">Toutes les questions de cette leçon sont validées. Tu peux passer à la suite.</p>':''}`}
function aStepPrimaryButton(){if(aTab==='read'&&aStep.type!=='checkpoint')return '<button class="primary" data-a="practice-start">Passer aux exercices →</button>';if(aTab==='walk'&&aStep.type!=='checkpoint')return `<button class="primary" data-a="walk-next">${aWalk<(aStep.walkthrough||[]).length-1?'Étape du pas à pas suivante':'Passer aux exercices'} →</button>`;const status=aPracticeStatus();if(!status.complete)return status.currentPassed?'<button class="primary" data-a="practice-next">Question suivante →</button>':'<button class="primary" data-a="practice-check">Vérifier ma réponse</button>';const label=aStep.type==='projet'?'Terminer le projet':aStep.course?(Number(aStep.id)+1<aStep.course.lessons.length?'Leçon suivante':'Terminer la série de leçons'):'Étape suivante';return `<button class="primary" data-a="complete-step">${esc(label)} →</button>`}
function aSyncStepFooter(){const footer=$('.a-lesson-footer'),button=footer?.querySelector('button.primary');if(button&&aStep)button.outerHTML=aStepPrimaryButton()}
function aMoveQuestion(index){aRememberInputs();aPracticeIndex=index;state.academy.practice[aRoute.id+'-'+aStep.id]=index;aPersist();aRenderPanel();const heading=$('.a-question h2');heading?.focus({preventScroll:true});heading?.scrollIntoView({block:'start',behavior:'instant'})}
function aRenderPanel(){const panel=$('#a-lesson-panel');if(!panel)return;panel.innerHTML=aStepPanel();$$('.a-lesson-tabs button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===aTab)));aRenderMath();aSyncStepFooter()}
function aRenderMath(){const nodes=$$('[data-a-math]');if(!nodes.length)return;if(!document.querySelector('link[data-katex]')){const link=document.createElement('link');link.rel='stylesheet';link.href='./vendor/katex.min.css';link.dataset.katex='true';document.head.append(link)}if(window.katex){nodes.forEach(n=>window.katex.render(n.dataset.aMath,n,{throwOnError:false,displayMode:true}));return}if(!document.querySelector('script[data-katex]')){const script=document.createElement('script');script.src='./vendor/katex.min.js';script.dataset.katex='true';script.onload=aRenderMath;document.head.append(script)}}
