function aAbroadView(){const g=aAbroad.find(x=>x.id===(aRoute.id||aDestination))||aAbroad[0],checks=state.academy.checklists[g.id]||{};return aPageHead('abroad',at('generalNotice'))+`<div class="a-destinations">${aAbroad.map(x=>`<a class="secondary ${x.id===g.id?'selected':''}" href="#/etranger/${x.id}" ${x.id===g.id?'aria-current="page"':''}>${esc(aLabel(x.title_fr,x.title_en))}</a>`).join('')}</div><section class="a-path-hero"><h2>${esc(g.title_fr)}</h2><p>${esc(g.overview_fr)}</p><small>${esc(at('sourceChecked'))} · ${esc(g.last_verified)}</small></section><form id="a-checklist-form" class="panel"><h2>${esc(at('checklist'))}</h2><label>${esc(at('date'))}<input type="date" name="date" value="${esc(checks.date||'')}" required></label><button class="secondary">${esc(at('generate'))}</button></form>${checks.date?`<section class="panel"><p>${esc(at('target'))} : ${esc(checks.date)}</p>${g.steps.map(s=>`<label class="a-check"><input type="checkbox" data-a-check="${s.id}" ${checks[s.id]?'checked':''}>${esc(s.title_fr)}</label>`).join('')}</section>`:''}<div class="a-guide-steps">${g.steps.map((s,i)=>`<section class="panel"><span class="eyebrow">0${i+1}</span><h2>${esc(s.title_fr)}</h2><p>${esc(s.text_fr)}</p><details><summary>${esc(at('documents'))}</summary><ul>${s.documents.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details></section>`).join('')}</div><details class="panel"><summary>${esc(at('tests'))} · ${esc(at('financing'))}</summary><p>${esc(g.tests_fr)}</p><p>${esc(g.finance_fr)}</p><a href="${esc(g.visa_url)}" target="_blank" rel="noopener">${esc(at('visa'))} ↗</a></details><section class="panel"><h2>${esc(at('scams'))}</h2><p>${esc(at('scamText'))}</p></section><details class="panel"><summary>${esc(at('sources'))}</summary>${g.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a> · ${esc(s.last_checked)}</p>`).join('')}</details>`}
function aOpportunityView(){const today=new Date(),list=aOpps.filter(o=>(!o.deadline||new Date(o.deadline)>=today)&&(aOpportunityType==='all'||o.type===aOpportunityType));return aPageHead('opportunities',at('oppsIntro'))+`<details class="panel"><summary>${esc(at('scams'))}</summary><p>${esc(at('scamText'))}</p></details><label class="a-opp-filter">${esc(at('type'))}<select id="a-opportunity-type">${['all','bourse','stage','formation','benevolat'].map(k=>`<option ${k===aOpportunityType?'selected':''} value="${k}">${esc(k==='all'?at('all'):k)}</option>`).join('')}</select></label><div class="a-opportunity-grid">${list.map(o=>`<article class="panel a-opportunity-card"><span class="eyebrow">${esc(o.type)} · ${esc(o.location)}</span><h2>${esc(o.title)}</h2><p>${esc(o.description_fr)}</p><small>${esc(o.organization)} · ${esc(at('sourceChecked'))} ${esc(o.last_checked)}</small><details><summary>${esc(at('eligibility'))}</summary><p>${esc(o.eligibility)}</p><p>${esc(o.cost)}</p></details><p>${o.deadline?`${esc(at('deadline'))} : ${new Date(o.deadline).toLocaleDateString('fr-TG',{day:'numeric',month:'long',year:'numeric'})}`:esc(at('portal'))}</p><div class="a-inline-actions"><a class="secondary" href="${esc(o.link)}" target="_blank" rel="noopener">${esc(at('official'))}</a><button class="text-button" data-a="save-opp" data-id="${o.id}">${esc(at(state.academy.savedOpps.includes(o.id)?'savedOpp':'saveOpp'))}</button>${o.deadline?`<button class="text-button" data-a="ics" data-id="${o.id}">${esc(at('remind'))}</button>`:''}</div></article>`).join('')}</div><section class="panel"><h2>${esc(at('mentors'))}</h2><p>${esc(at('mentorSoon'))}</p><p>${esc(at('employersSoon'))}</p><label class="a-check"><input type="checkbox" id="a-interest-consent" ${state.academy.interest.mentors?'checked':''}>${esc(at('interestConsent'))}</label><button class="secondary" data-a="mentor-interest">${esc(at('interestLocal'))}</button></section>`}
function aPortfolio(){const cv=state.academy.cv,projects=[...Object.entries(state.academy.projects).filter(([,text])=>text.trim()),...Object.values(state.localProjects||{}).filter(p=>p.idea?.trim()).map(p=>[p.title,[p.idea,p.observations,p.nextStep].filter(Boolean).join('\n\n')])],fields=[['role','cvRole'],['about','cvAbout'],['education','education'],['experience','experience'],['skills','skills'],['letter','letter']];return aPageHead('portfolio',at('cvPrivacy'))+`<section class="panel"><h2>${esc(at('project'))}</h2>${projects.length?projects.map(([id,text])=>`<details><summary>${esc(id.split('-').slice(-2).join(' '))}</summary><p class="a-preserve">${esc(text)}</p></details>`).join(''):`<p>${esc(at('emptyPortfolio'))}</p>${aLink('#/avenir','browse')}`}<p>${esc(at('selfAssessment'))}</p><p>${esc(at('publicLater'))}</p></section><form id="a-cv-form" class="panel"><h2>${esc(at('cv'))} & ${esc(at('letter'))}</h2>${fields.map(([key,label])=>`<label>${esc(at(label))}<textarea name="${key}" rows="${key==='letter'?6:3}" maxlength="6000">${esc(cv[key]||'')}</textarea></label>`).join('')}<div class="a-inline-actions"><button class="secondary">${esc(at('save'))}</button><button type="button" class="secondary" data-a="print-cv">${esc(at('print'))}</button></div></form><section id="a-cv-preview" class="panel a-cv-preview"><h2>${esc(cv.role||at('cv'))}</h2>${fields.filter(([key])=>key!=='role'&&cv[key]).map(([key,label])=>`<h3>${esc(at(label))}</h3><p class="a-preserve">${esc(cv[key])}</p>`).join('')}<footer>${esc(at('selfAssessment'))}</footer></section><section class="panel"><h2>${esc(at('interview'))}</h2><label>${esc(at('interviewPrompt'))}<textarea id="a-interview" rows="4" maxlength="4000">${esc(cv.interview||'')}</textarea></label><button class="secondary" data-a="interview">${esc(at('criteria'))}</button><p id="a-interview-feedback"></p></section>`}
