document.addEventListener('submit',e=>{if(!['a-onboard','a-weekly','a-checklist-form','a-cv-form'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();const f=new FormData(e.target);if(e.target.id==='a-onboard'){if(!f.get('age'))return;state.profile.name=String(f.get('name')||'').slice(0,30);state.preferredTrack=f.get('goal');state.academy.onboarded=true;aPersist();aGo(state.preferredTrack==='school'?'#/mes-cours':'#/avenir')}if(e.target.id==='a-weekly'){state.academy.weekly[aRoute.id]=Math.max(.5,Math.min(20,Number(f.get('hours'))||3));aPersist();render()}if(e.target.id==='a-checklist-form'){const g=aAbroad.find(x=>x.id===(aRoute.id||aDestination))||aAbroad[0];state.academy.checklists[g.id]={...(state.academy.checklists[g.id]||{}),date:String(f.get('date'))};aPersist();render()}if(e.target.id==='a-cv-form'){for(const [key,v]of f)state.academy.cv[key]=String(v).slice(0,6000);aPersist();render();toast(at('noticeSaved'))}},true);
document.addEventListener('click',async e=>{const a=e.target.closest('a[href^="#/"]');if(a){e.preventDefault();e.stopImmediatePropagation();aGo(a.getAttribute('href'));return}const b=e.target.closest('[data-a],#a-more');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const action=b.dataset.a;if(b.id==='a-more'){const open=$('#sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String(open));syncMenuAccess();if(open)$('#sidebar a').focus();return}if(action==='retry'){aResolve();return}if(action==='tab'){aRememberInputs();aTab=b.dataset.tab;aRenderPanel();return}if(action==='walk-prev'||action==='walk-next'){const len=aStep.walkthrough.length;if(action==='walk-prev')aWalk--;else if(aWalk<len-1)aWalk++;else aTab='practice';aRenderPanel();return}if(action==='answer'){const key=aRoute.id+'-'+b.dataset.q;state.academy.answers[key]={...(state.academy.answers[key]||{}),value:Number(b.dataset.value),checked:false,correct:false};aPersist();aRenderPanel();return}if(action==='practice-start'){aRememberInputs();aTab='practice';aRenderPanel();$('.a-question h2')?.focus();return}if(action==='practice-prev'){if(aPracticeIndex>0)aMoveQuestion(aPracticeIndex-1);return}if(action==='practice-next'){const status=aPracticeStatus();if(status.currentPassed&&status.nextIndex>=0)aMoveQuestion(status.nextIndex);return}if(action==='practice-check'||action==='grade'||action==='hint'){aRememberInputs();const q=aStep.practice.find(q=>q.id===(b.dataset.q||aStep.practice[aPracticeIndex]?.id)),key=aRoute.id+'-'+q.id,w=state.academy.answers[key]||(state.academy.answers[key]={value:'',hints:0});if(action==='grade'||action==='practice-check'){w.correct=academyGrade(q,w.value);w.checked=true}else w.hints=Math.min(3,(w.hints||0)+1);aPersist();aRenderPanel();return}if(action==='complete-step'){aRememberInputs();if(!aPracticeStatus().complete){aTab='practice';aRenderPanel();toast(at('finishPractice'));return;}const questions=aStep.practice||[];if(!questions.every(q=>state.academy.answers[aRoute.id+'-'+q.id]?.correct)){aTab='practice';aRenderPanel();toast(at('finishPractice'));return}if(aStep.type==='projet'&&(state.academy.projects[aRoute.id+'-'+aStep.id]||'').trim().length<30){toast(at('needProject'));return}if(aStep.course){const c=aStep.course,key=c.id+':'+aStep.id;if(!state.done.includes(key))state.done.push(key);aPersist();const next=Number(aStep.id)+1;aGo(next<c.lessons.length?'#/parcours/cours-'+c.id+'/etape/'+next:'#/parcours/cours-'+c.id);return}const p=aPath(aRoute.id),stage=p.stages.find(s=>s.steps.some(x=>x.id===aStep.id));if(aRoute.challenge){for(const s of stage.steps)state.academy.progress[s.id]={complete:true,at:new Date().toISOString()};}else state.academy.progress[aStep.id]={complete:true,at:new Date().toISOString()};state.academy.activePath=p.id;const next=academyNext(p,state.academy.progress);aPersist();aGo(next?'#/parcours/'+p.id+'/etape/'+next.id:'#/portfolio');return}if(action==='testout'){const p=aPath(aRoute.id),stage=p.stages.find(s=>s.id===b.dataset.stage),checkpoint=stage.steps.find(x=>x.type==='checkpoint');await aGo('#/parcours/'+p.id+'/etape/'+checkpoint.id);aRoute.challenge=true;aTab='practice';render();return}if(action==='download-path'){b.disabled=true;await aDownloadPath(b.dataset.id);return}if(action==='download-course'){await saveDownload(b.dataset.id);return}if(action==='save-work'||action==='save-project'){aRememberInputs();aPersist();toast(at('noticeSaved'));return}if(action==='blocked'){aTab='practice';aRenderPanel();$('.a-question')?.scrollIntoView({block:'start'});return}if(action==='code'){activeCourse=aStep.course;activeLesson=aStep.courseIndex;const lang=aStepCodeLanguage();$('#a-code-panel').innerHTML=editorMarkup(lang,aStep.coding?.code||aStep.code||'');return}if(action==='speak'){if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(aStep.body.join(' '));u.lang='fr-FR';speechSynthesis.speak(u);return}if(action==='placement'){startPlacement();return}if(action==='legacy-school'){aGo('#/mes-cours/catalogue');return}if(action==='interest-answer'){aInterestAnswers.push({domain:aInterestQuestions[aQuizIndex][2],score:Number(b.dataset.value)});aQuizIndex++;if(aQuizIndex===8){const totals={};for(const x of aInterestAnswers)totals[x.domain]=(totals[x.domain]||0)+x.score;aInterestResults=Object.entries(totals).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([id])=>id)}render();return}if(action==='save-opp'){if(!state.academy.savedOpps.includes(b.dataset.id))state.academy.savedOpps.push(b.dataset.id);aPersist();render();return}if(action==='ics'){const item=aOpps.find(o=>o.id===b.dataset.id),text=academyIcs(item);if(text){const url=URL.createObjectURL(new Blob([text],{type:'text/calendar'})),a=document.createElement('a');a.href=url;a.download='nunya-'+item.id+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}return}if(action==='mentor-interest'){state.academy.interest.mentors=$('#a-interest-consent').checked;aPersist();toast(at('noticeSaved'));return}if(action==='interview'){state.academy.cv.interview=$('#a-interview').value;aPersist();$('#a-interview-feedback').textContent=at('interviewHint');return}if(action==='print-cv'){const form=$('#a-cv-form');if(form){const f=new FormData(form);for(const [key,v]of f)state.academy.cv[key]=String(v).slice(0,6000);aPersist();render()}window.print();return}if(action==='copy-link'){try{await navigator.clipboard.writeText(new URL('./',location.href).href);toast(at('noticeSaved'))}catch{toast(new URL('./',location.href).href)}return}if(action==='feedback'||action==='report-resource'){feedbackModal();return}if(action==='storage'){const s=await navigator.storage?.estimate();$('#a-storage-result').textContent=s?`${(s.usage/1048576).toFixed(1)} / ${(s.quota/1048576).toFixed(0)} Mo`:at('notDownloaded');return}},true);
